#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
unsigned int byte_oracle(const unsigned char*bytes,int len,unsigned int seed){unsigned int a=0xdeadbeef+len+seed,b=a,c=a;int pos=0;auto word=[&](int q,int count){unsigned int v=0;for(int j=0;j<count;j++)v|=(unsigned int)bytes[q+j]<<(8*j);return v;};while(len>12){a+=word(pos,4);b+=word(pos+4,4);c+=word(pos+8,4);mix(a,b,c);len-=12;pos+=12;}if(!len)return c;a+=word(pos,len<4?len:4);if(len>4)b+=word(pos+4,len-4<4?len-4:4);if(len>8)c+=word(pos+8,len-8);final(a,b,c);return c;}
struct Case{unsigned int*keys,*lens,*seeds,*out;std::vector<unsigned int>gold;};
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):100;if(repeat<1)return 2;int n=4099;unsigned char sample[64]={};memcpy(sample,"Four score and seven years ago",30);if(byte_oracle(sample,30,1)!=0xcd628161||hashlittle(sample,30,1)!=0xcd628161)return 3;std::vector<Case>cases;std::vector<unsigned int>prefix;for(int kind=0;kind<2;kind++){Case c;std::vector<unsigned int>keys(n*16),lens(n),seeds(n);for(int i=0;i<n;i++){if(!kind)memcpy(keys.data()+i*16,sample,64);else for(int w=0;w<16;w++)keys[i*16+w]=(uint32_t)(uint64_t(i+1)*2654435761ULL+uint64_t(w)*2246822519ULL);lens[i]=!kind?i%61:(i*17)%61;seeds[i]=!kind?i%2:UINT32_MAX-(uint32_t)i;unsigned int gold=byte_oracle((unsigned char*)(keys.data()+i*16),lens[i],seeds[i]);if(gold!=hashlittle(keys.data()+i*16,lens[i],seeds[i]))return 4;if(!lens[i]&&gold!=(unsigned int)(0xdeadbeef+seeds[i]))return 5;c.gold.push_back(gold);}prefix.insert(prefix.end(),keys.begin(),keys.end());prefix.insert(prefix.end(),lens.begin(),lens.end());prefix.insert(prefix.end(),seeds.begin(),seeds.end());CK(cudaMalloc(&c.keys,keys.size()*4));CK(cudaMalloc(&c.lens,n*4));CK(cudaMalloc(&c.seeds,n*4));CK(cudaMalloc(&c.out,n*4));CK(cudaMemcpy(c.keys,keys.data(),keys.size()*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(c.lens,lens.data(),n*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(c.seeds,seeds.data(),n*4,cudaMemcpyHostToDevice));jk3_hash_kernel<<<(n+255)/256,256>>>(c.lens,c.seeds,c.keys,c.out,n);cases.push_back(c);}CK(cudaDeviceSynchronize());bool allok=true;for(int trial=1;trial<=5;trial++){double seconds=0;bool ok=true;auto output=prefix;for(auto&c:cases){CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;rep++)jk3_hash_kernel<<<(n+255)/256,256>>>(c.lens,c.seeds,c.keys,c.out,n);CK(cudaDeviceSynchronize());seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;std::vector<unsigned int>got(n);CK(cudaMemcpy(got.data(),c.out,n*4,cudaMemcpyDeviceToHost));ok&=got==c.gold;output.insert(output.end(),got.begin(),got.end());}allok&=ok;char file[80];sprintf(file,"jenkins_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(output.data(),4,output.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"computed_hash_values\":8198,\"input_prefix_values\":147564,\"max_abs_error\":0,\"max_rel_error\":0,\"timing_region\":\"sum_two_complete_lookup3_hash_fixtures\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",output.size(),repeat,file,output.size());}for(auto&c:cases){CK(cudaFree(c.keys));CK(cudaFree(c.lens));CK(cudaFree(c.seeds));CK(cudaFree(c.out));}puts(allok?"PASS":"FAIL");return allok?0:1;}
